def main():
    print("🚀 Початок глобального наповнення баз укриттів міст, містечок та райцентрів України...")
    
    total_added = 0
    total_all_shelters = 0
    compiled_master_seeds = []

    for region_file in sorted(os.listdir(REGIONS_DIR)):
        if not region_file.endswith(".json"):
            continue

        region_code = region_file.replace(".json", "")
        region_path = os.path.join(REGIONS_DIR, region_file)

        with open(region_path, "r", encoding="utf-8") as f:
            existing_shelters = json.load(f)

        existing_ids = {s["id"] for s in existing_shelters}
        existing_names = {s["name"].lower() for s in existing_shelters}

        new_candidates = ALL_TOWNS_SHELTERS.get(region_code, [])
        added_count = 0

        for cand in new_candidates:
            if cand["id"] not in existing_ids and cand["name"].lower() not in existing_names:
                existing_shelters.append(cand)
                existing_ids.add(cand["id"])
                existing_names.add(cand["name"].lower())
                added_count += 1
                total_added += 1

        # Re-sort Tier 1 Primary first, then Tier 2 Secondary
        sorted_shelters = sorted(
            existing_shelters,
            key=lambda x: (
                0 if x.get("is_primary") else 1,
                0 if x.get("is_vehicle_accessible") else 1,
                x.get("name", "")
            )
        )

        with open(region_path, "w", encoding="utf-8") as f:
            json.dump(sorted_shelters, f, ensure_ascii=False, indent=2)

        compiled_master_seeds.extend(sorted_shelters)
        total_all_shelters += len(sorted_shelters)
        
        tier1_count = sum(1 for s in sorted_shelters if s.get("is_primary"))
        tier2_count = sum(1 for s in sorted_shelters if not s.get("is_primary"))
        print(f"  ✅ {region_file}: {len(sorted_shelters)} укриттів (Tier 1: {tier1_count}, Tier 2: {tier2_count}) [+ {added_count} нових з містечок]")

    # Save to master shelters_seed.json
    compiled_unique = []
    seen_master_ids = set()
    for s in compiled_master_seeds:
        if s["id"] not in seen_master_ids:
            compiled_unique.append(s)
            seen_master_ids.add(s["id"])

    with open(MASTER_SEED_PATH, "w", encoding="utf-8") as f:
        json.dump(compiled_unique, f, ensure_ascii=False, indent=2)

    print(f"\n🌟 УСПІШНО ОНОВЛЕНО {len(compiled_unique)} УКРИТТІВ ПО ВСІХ МІСТАХ ТА МІСТЕЧКАХ УКРАЇНИ!")
    print(f"   - Додано нових укриттів: {total_added}")
    print(f"   - Збережено у {MASTER_SEED_PATH}\n")


if __name__ == "__main__":
    main()
